-- Out of Station: configurable approval stages (like payroll), replacing the supervisor → HR tiers.
-- Idempotent. Run after 20261026_out_of_station.postgres.sql.
--
-- The flow itself is the `out_of_station_approval_flow` app-control (JSON, set in Settings → Controls →
-- Approvals). When a request is submitted the flow is copied here, one row per stage, so editing the
-- flow never changes a request already in approval. Ids are generated by the application.

CREATE TABLE IF NOT EXISTS outofstation_stages (
  id             BIGINT       PRIMARY KEY,
  request_id     BIGINT       NOT NULL,
  stage_order    INT          NOT NULL,
  stage_name     VARCHAR(150) NOT NULL,
  approver_type  VARCHAR(10)  NOT NULL,              -- 'role' | 'user'
  approver_id    VARCHAR(64)  NOT NULL,
  approver_label VARCHAR(200),
  status         VARCHAR(20)  NOT NULL DEFAULT 'Pending',   -- Pending | Approved | Rejected | Skipped
  acted_by       BIGINT,
  acted_at       TIMESTAMP(0),
  comment        TEXT,
  created_at     TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS outofstation_stages_request_idx ON outofstation_stages (request_id, stage_order);

-- The supervisor tier is gone: requests waiting at either old tier become 'Pending Approval' with no
-- stages, which anyone with approve_out_of_station approves in one step.
UPDATE outofstation_requests SET status = 'Pending Approval' WHERE status = 'Pending HR Approval';

-- The supervisor-approval switch no longer exists.
DELETE FROM settings WHERE category = 'out_of_station' AND name = 'oos_supervisor_approval';
